  logic aw_ok, ar_ok;
  logic [Bytes-1:0] write_lanes;
  logic [63:0] beat_word;
  logic found;

  // sv-timing: cut #95 moved service_ready_o <- (rst_ni && ModelLegal) via pipe_svt_p1_19 (declared below)
