      resp_o.b.id = q.w_id;
      resp_o.b.user = q.w_user;
      resp_o.b.resp = q.b_error ? RespSlvErr : 2'b00;
      resp_o.r_valid = q.r_valid;
      resp_o.r.id = q.r_id;
      resp_o.r.user = q.r_user;
      resp_o.r.data = q.r_data;
      resp_o.r.resp = q.r_error ? RespSlvErr : 2'b00;
