        d.r_len = req_i.ar.len;
        d.r_left = req_i.ar.len;
        d.r_beat = 0;
        d.r_size = req_i.ar.size;
        d.r_burst = req_i.ar.burst;
        d.r_source = source_i;
        d.r_generation = reset_generation_i;
        d.r_fault = 1'b1;
